// Legacy v12 synth ids -> closest Forge wav (old clients still work).
export const LEGACY_BOARD_MAP = {
  airhorn: 'alarm', rimshot: 'drum_snare', applause: 'drum_clap',
  trombone: 'undo', boing: 'bubble', ding: 'ding', pop: 'pop',
  fart: 'boop', cat: 'boop', wow: 'surprised', crickets: 'clock_tick',
  tada: 'victory', laser: 'laser', siren: 'alarm', drumroll: 'drum_snare',
  yay: 'achievement'
};

const VOLUME_KEY = 'hush:soundboard-volume';
const IDS = new Set(SOUNDBOARD_SOUNDS.map((s) => s.id));

let volume = 0.7;
try {
  const saved = Number(localStorage.getItem(VOLUME_KEY));
  if (Number.isFinite(saved) && saved > 0) volume = Math.min(1, Math.max(0, saved));
} catch { /* ignore */ }

export function isSoundboardId(id) { return IDS.has(id); }
export function getSoundboardVolume() { return volume; }
export function setSoundboardVolume(value) {
  volume = Math.min(1, Math.max(0, Number(value) || 0));
  try { localStorage.setItem(VOLUME_KEY, String(volume)); } catch { /* ignore */ }
}

// Play a built-in Forge wav, reusing one <audio> per id (decoded once).
const boardAudioCache = new Map();
export function playSoundboard(id) {
  const realId = LEGACY_BOARD_MAP[id] || id;
  if (!IDS.has(realId)) return false;
  try {
    let audio = boardAudioCache.get(realId);
    if (!audio) {
      audio = new Audio(`/sounds/${encodeURIComponent(realId)}.wav`);
      audio.preload = 'auto';
      boardAudioCache.set(realId, audio);
    }
    audio.volume = volume;
    try { audio.currentTime = 0; } catch { /* not seekable yet */ }
    const p = audio.play();
    if (p && typeof p.catch === 'function') p.catch(() => {});
    return true;
  } catch { return false; }
}

// Custom (uploaded) room/server sounds: play the audio file, reusing one
// <audio> per URL so repeats don't re-fetch.
const customAudioCache = new Map();
export function playCustomSound(url) {
  if (typeof url !== 'string' || !url.startsWith('/uploads/') || url.includes('..')) return false;
  try {
    let audio = customAudioCache.get(url);
    if (!audio) { audio = new Audio(url); audio.preload = 'auto'; customAudioCache.set(url, audio); }
    audio.volume = volume;
    try { audio.currentTime = 0; } catch { /* ignore */ }
    audio.play().catch(() => {});
    return true;
  } catch { return false; }
}

// Personal sounds stored on-device (IndexedDB): play from a Blob URL.
const blobAudioCache = new Map();
export function playBlobSound(blobUrl, { volume: vol } = {}) {
  if (typeof blobUrl !== 'string' || !blobUrl.startsWith('blob:')) return false;
  try {
    let audio = blobAudioCache.get(blobUrl);
    if (!audio) { audio = new Audio(blobUrl); audio.preload = 'auto'; blobAudioCache.set(blobUrl, audio); }
    audio.volume = typeof vol === 'number' ? vol : volume;
    try { audio.currentTime = 0; } catch { /* ignore */ }
    audio.play().catch(() => {});
    return true;
  } catch { return false; }
}

export function soundboardEmojiId(id) {
  const realId = LEGACY_BOARD_MAP[id] || id;
  return SOUNDBOARD_SOUNDS.find((s) => s.id === realId)?.emojiId
    || EMOJI_FOR[realId] || 'star';
}

export function soundboardCategory(id) {
  return SOUNDBOARD_SOUNDS.find((s) => s.id === id)?.cat || 'ui';
}
